    public var address: String

    /// Default memberwise initializers are never public by default, so we
    /// declare one manually.
    public init(
        /* 
         * The 12-word BIP-39 recovery phrase. **This is the secret.** It restores
         * the wallet anywhere, forever.
         */ mnemonic: String,
        /* 
            * The `zkas:` shielded address the phrase derives.
            */ address: String
    ) {
        self.mnemonic = mnemonic
        self.address = address
    }
}

extension GeneratedWallet: Equatable, Hashable {
    public static func == (lhs: GeneratedWallet, rhs: GeneratedWallet) -> Bool {
        if lhs.mnemonic != rhs.mnemonic {
            return false
        }
        if lhs.address != rhs.address {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(mnemonic)
        hasher.combine(address)
    }
}

