public enum SignerError {
    /**
     * The underlying signer refused the input. Safe to show: it never contains
     * key material.
     *
     * The field is `reason`, not `message`. UniFFI turns this into a Kotlin
     * class extending Exception, which already declares `message` — naming it
     * that produces a conflicting declaration that fails the Kotlin build while
     * Swift compiles happily, so the clash only shows up on one platform.
     */
    case Signer(reason: String)
}

#if swift(>=5.8)
    @_documentation(visibility: private)
#endif
public struct FfiConverterTypeSignerError: FfiConverterRustBuffer {
    typealias SwiftType = SignerError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> SignerError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return try .Signer(
                reason: FfiConverterString.read(from: &buf)
            )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SignerError, into buf: inout [UInt8]) {
        switch value {
        case let .Signer(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
        }
    }
}

extension SignerError: Equatable, Hashable {}

extension SignerError: Foundation.LocalizedError {
    public var errorDescription: String? {
        String(reflecting: self)
    }
}

/**
 * The address of one account of a phrase, without handling the key.
 *
 * Accounts are `m/32'/111111'/account'`. Useful for showing a user their
 * accounts, or discovering which ones have history, without deriving keys.
 */
public func accountAddress(phrase: String, network: String, account: UInt32) throws -> String {
    return try FfiConverterString.lift(rustCallWithError(FfiConverterTypeSignerError.lift) {
        uniffi_zkas_mobile_fn_func_account_address(
            FfiConverterString.lower(phrase),
            FfiConverterString.lower(network),
            FfiConverterUInt32.lower(account), $0
        )
    })
}

/**
 * Generate a new wallet: a 12-word recovery phrase and its address.
 *
 * Twelve words is not a shortcut. An Orchard key lives on the Pallas curve,
 * whose ~128-bit security caps what any seed can buy; a longer phrase would be
 * more to write down for no more strength.
 */
public func generateWallet(network: String) throws -> GeneratedWallet {
    return try FfiConverterTypeGeneratedWallet.lift(rustCallWithError(FfiConverterTypeSignerError.lift) {
        uniffi_zkas_mobile_fn_func_generate_wallet(
            FfiConverterString.lower(network), $0
        )
    })
}

/**
