 * caught before it becomes an empty wallet.
 */
public func isValidMnemonic(phrase: String) -> Bool {
    return try! FfiConverterBool.lift(try! rustCall {
        uniffi_zkas_mobile_fn_func_is_valid_mnemonic(
            FfiConverterString.lower(phrase), $0
        )
    })
}

/**
 * Check a signature made by `Signer::sign_message` against an address.
 * Needs no key, so it is safe to run anywhere.
 */
public func verifyMessage(address: String, message: String, signatureHex: String) throws -> Bool {
    return try FfiConverterBool.lift(rustCallWithError(FfiConverterTypeSignerError.lift) {
        uniffi_zkas_mobile_fn_func_verify_message(
            FfiConverterString.lower(address),
            FfiConverterString.lower(message),
            FfiConverterString.lower(signatureHex), $0
        )
    })
}

private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}

/// Use a global variable to perform the versioning checks. Swift ensures that
/// the code inside is only computed once.
private var initializationResult: InitializationResult = {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 26
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_zkas_mobile_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if uniffi_zkas_mobile_checksum_func_account_address() != 1057 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_func_generate_wallet() != 31304 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_func_is_valid_mnemonic() != 52094 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_func_verify_message() != 13469 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_method_signer_account_key() != 59785 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_method_signer_address() != 16517 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_method_signer_sign_message() != 52243 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_method_signer_verify_and_sign_payment() != 43587 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_method_signer_viewing_key() != 18334 {
        return InitializationResult.apiChecksumMismatch
    }
    if uniffi_zkas_mobile_checksum_constructor_signer_from_secret() != 64227 {
        return InitializationResult.apiChecksumMismatch
    }

    return InitializationResult.ok
}()

private func uniffiEnsureInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

